    "เปลี่ยนตัวแปรสร้างสรรค์ครั้งละหนึ่งอย่าง",
  "Change or withdraw": "เปลี่ยนหรือถอน",
  "Change the filters or run custom research. REELassati will show fewer results rather than fill the feed with stale, paid, generic, or unverified content.":
    "เปลี่ยนตัวกรองหรือทำวิจัยเฉพาะ REELassati จะแสดงผลน้อยลงแทนการเติมฟีดด้วยเนื้อหาเก่า โฆษณา เนื้อหาทั่วไป หรือที่ยังไม่ตรวจสอบ",
  "Change the search or filter to reveal more items.":
    "เปลี่ยนคำค้นหาหรือตัวกรองเพื่อดูรายการเพิ่มเติม",
  "Changes appear on your timeline as they finish. You can keep editing them by hand.":
    "การเปลี่ยนแปลงปรากฏบนไทม์ไลน์เมื่อเสร็จ คุณยังแก้ไขด้วยตนเองได้",
  "Changes are saved as an undoable revision.":
    "บันทึกการเปลี่ยนแปลงเป็นเวอร์ชันที่ย้อนกลับได้",
  "Changes need attention": "การเปลี่ยนแปลงต้องตรวจสอบ",
  "Chapter heading, supporting line and an expanding rule.":
    "หัวข้อบท บรรทัดประกอบ และเส้นที่ขยายออก",
  "Chapter marker": "เครื่องหมายบท",
  "Chapter opener": "เปิดบท",
