  Title: "ชื่อเรื่อง",
  "Title pop": "ชื่อเรื่องป๊อป",
  To: "ถึง",
  "To the extent permitted by providers and law, you may use outputs created for you. Outputs may not be exclusive and do not transfer third-party rights. Human review and destination-platform rules still apply.":
    "ภายในขอบเขตที่ผู้ให้บริการและกฎหมายอนุญาต คุณใช้ผลลัพธ์ที่สร้างให้คุณได้ ผลอาจไม่เป็นเอกสิทธิ์และไม่โอนสิทธิ์บุคคลอื่น ยังต้องมีการตรวจโดยมนุษย์และทำตามกฎแพลตฟอร์มปลายทาง",
