  "Top-ups require an active subscription, roll over, and remain usable while a plan is active. They are not money, are not transferable, and are non-refundable except where law or the Refund Policy requires otherwise.":
    "การเติมเครดิตต้องมีสมาชิกที่ใช้งาน ทบยอดได้ และใช้ได้ขณะแพ็กเกจใช้งาน ไม่ใช่เงิน โอนไม่ได้ และคืนไม่ได้ เว้นแต่กฎหมายหรือนโยบายคืนเงินกำหนด",
  "Topic, audience, key points, and the action you want viewers to take…":
    "หัวข้อ ผู้ชม ประเด็นหลัก และการกระทำที่ต้องการจากผู้ชม…",
  "Topic, niche, product, or audience": "หัวข้อ กลุ่มเฉพาะ ผลิตภัณฑ์ หรือผู้ชม",
