  "Use a public link. Upload the file if the source requires sign-in.":
    "ใช้ลิงก์สาธารณะ อัปโหลดไฟล์หากแหล่งต้องเข้าสู่ระบบ",
  "Use a source-linked trend above or add your own observation.":
    "ใช้เทรนด์ที่ลิงก์ต้นฉบับด้านบนหรือเพิ่มข้อสังเกตของคุณ",
  "Use a transparent PNG or WebP for a logo without a background.":
    "ใช้ PNG หรือ WebP โปร่งใสสำหรับโลโก้ไม่มีพื้นหลัง",
  "Use an available sign-in provider or complete the name, email, and password fields. Use an email address you can access.":
    "ใช้ผู้ให้บริการเข้าสู่ระบบที่มีหรือกรอกชื่อ อีเมล และรหัสผ่าน ใช้อีเมลที่เข้าถึงได้",
  "Use as starting point": "ใช้เป็นจุดเริ่มต้น",
  "Use at least 8 characters. Your new password replaces the old one immediately.":
    "ใช้อย่างน้อย 8 อักขระ รหัสใหม่แทนรหัสเก่าทันที",
  "Use call to action {{number}}": "ใช้คำกระตุ้นการตัดสินใจ {{number}}",
  "Use connected accounts": "ใช้บัญชีที่เชื่อมต่อ",
  "Use dark theme": "ใช้ธีมมืด",
