    "ใช้ข้อความถอดเสียงเป็นสื่อสำหรับบทวิดีโอสั้น กำหนดผู้ชมและผลลัพธ์ชัดแทนการเก็บทุกคำพูดออกนอกเรื่อง",
  "Use this call to action": "ใช้คำกระตุ้นการตัดสินใจนี้",
  "Use this opening": "ใช้ฉากเปิดนี้",
  "Use wider spacing to stay within 48 cut points.":
    "เพิ่มระยะห่างเพื่อให้จุดตัดไม่เกิน 48 จุด",
  "Use your active goals alongside Weekly Review to decide what to finish next.":
    "ใช้เป้าหมายที่ทำอยู่ร่วมกับทบทวนรายสัปดาห์เพื่อตัดสินใจว่างานใดควรเสร็จถัดไป",
  "Use your existing account": "ใช้บัญชีเดิม",
  "User-selected content and instructions: prompts, scripts, files, media, projects, preferences, and outputs.":
    "เนื้อหาและคำสั่งที่ผู้ใช้เลือก: พรอมป์ต์ บท ไฟล์ สื่อ โปรเจกต์ การตั้งค่า และผลลัพธ์",
  "Uses existing media and measured speech. No AI credits. Apply creates one saved revision; Undo restores the previous edit.":
    "ใช้สื่อเดิมและเสียงพูดที่วัดแล้ว ไม่ใช้เครดิต AI ใช้สร้างเวอร์ชันบันทึกหนึ่งฉบับ ย้อนกลับคืนงานตัดต่อก่อนหน้า",
  "Uses measured word timings from transcription. Imported subtitles or edited lines without word timings display the whole phrase.":
    "ใช้เวลาแต่ละคำที่วัดจากการถอดเสียง คำบรรยายที่นำเข้าหรือบรรทัดแก้ไขที่ไม่มีเวลาแต่ละคำจะแสดงทั้งวลี",
  "Uses unused footage around the cut. Speech timing and total edit length stay fixed. Other overlapping video layers must be resolved first.":
    "ใช้ฟุตเทจที่ยังไม่ใช้รอบจุดตัด เวลาเสียงพูดและความยาวงานรวมคงที่ ต้องแก้เลเยอร์วิดีโออื่นที่ซ้อนก่อน",
  Verified: "ยืนยันแล้ว",
  "Verified output": "ผลลัพธ์ที่ยืนยันแล้ว",
  "Verified weekly picks are not available yet. Keep creating from your own idea while the next automatic check runs.":
    "รายการประจำสัปดาห์ที่ยืนยันยังไม่พร้อม สร้างจากไอเดียของคุณต่อระหว่างรอการตรวจอัตโนมัติถัดไป",
  "Version history and finished MP4 exports":
    "ประวัติเวอร์ชันและไฟล์ MP4 ส่งออกที่เสร็จ",
