  "Video analysis · minute": "วิเคราะห์วิดีโอ · นาที",
  "Video continuation started": "เริ่มต่อวิดีโอแล้ว",
  "Video duration": "ความยาววิดีโอ",
  "Video generated": "สร้างวิดีโอแล้ว",
  "Video generation": "การสร้างวิดีโอ",
  "Video generation failed": "สร้างวิดีโอไม่สำเร็จ",
  "Video generation is not configured": "ยังไม่ตั้งค่าการสร้างวิดีโอ",
  "Video generation is temporarily unavailable. Prompt design remains available in the meantime.":
    "การสร้างวิดีโอไม่พร้อมชั่วคราว ยังออกแบบพรอมป์ต์ได้ในระหว่างนี้",
