    "คุณยังเป็นเจ้าของเนื้อหาที่อัปโหลด คุณให้สิทธิ์จำกัดแก่ REELassati และผู้ให้บริการที่จำเป็นเพื่อโฮสต์ ประมวลผล แปลง และส่งเนื้อหาเฉพาะเพื่อคุณสมบัติที่ร้องขอ คุณรับผิดชอบสิทธิ์ ใบอนุญาต ความยินยอม และการอนุญาตที่จำเป็น รวมถึงภาพหรือเสียงบุคคลจริง",
